                          (Z_to_bv 64 (tr_calls L c0)) (Z_to_bv 64 0) (Z_to_bv 64 TR_M2) s8 s9 s10 s11 t3 t4 t5 t6 F fc 0x963fc m)
    (entry_st ra (Z_to_bv 64 sp) gp (Z_to_bv 64 TP_A) t0 t1 t2 (Z_to_bv 64 0) (Z_to_bv 64 pp) a0 a1 a2 a3 a4 a5 a6 a7
